/** bool8 ShouldIgnoreDeoxysForm(u8 caseId, u8 battler) */
export function ShouldIgnoreDeoxysForm(caseId: any, battler: any): any {
  switch (caseId)
      {
      case 0:
      default:
          return FALSE;
      case 1:  
          if (!(gBattleTypeFlags & ((1 << 6))))
              return FALSE;
          if (!gMain.inBattle)
              return FALSE;
          if (gLinkPlayers[GetMultiplayerId()].id == battler)
              return FALSE;
          break;
      case 2:
          break;
      case 3:  
          if (!(gBattleTypeFlags & ((1 << 6))))
              return FALSE;
          if (!gMain.inBattle)
              return FALSE;
          if (battler == 1 || battler == 4 || battler == 5)
              return TRUE;
          return FALSE;
      case 4:
          break;
      case 5:  
          if (gBattleTypeFlags & ((1 << 1)))
          {
              if (!gMain.inBattle)
                  return FALSE;
              if (gBattleTypeFlags & ((1 << 6)))
              {
                  if (gLinkPlayers[GetMultiplayerId()].id == battler)
                      return FALSE;
              }
              else
              {
                  if (GetBattlerSide(battler) == (0))
                      return FALSE;
              }
          }
          else
          {
              if (!gMain.inBattle)
                  return FALSE;
              if (GetBattlerSide(battler) == (0))
                  return FALSE;
          }
          break;
      }

      return TRUE;
}

/** static u16 GetDeoxysStat(struct Pokemon *mon, s32 statId) */
export function GetDeoxysStat(mon: any, statId: any): any {
  let ivVal, evVal;
      let statValue: any = 0;
      let nature: any = null;

      if (gBattleTypeFlags & ((1 << 5)) || GetMonData(mon, MON_DATA_SPECIES, NULL) != (410))
          return 0;

      ivVal = GetMonData(mon, MON_DATA_HP_IV + statId, NULL);
      evVal = GetMonData(mon, MON_DATA_HP_EV + statId, NULL);
      statValue = ((sDeoxysBaseStats[statId] * 2 + ivVal + evVal / 4) * mon.level) / 100 + 5;
      nature = GetNature(mon);
      statValue = ModifyStatByNature(nature, statValue, statId);
      return statValue;
}

