/** u8 GetBoxMonGender(struct BoxPokemon *boxMon) */
export function GetBoxMonGender(boxMon: any): any {
  let species: any = GetBoxMonData(boxMon, MON_DATA_SPECIES, NULL);
      let personality: any = GetBoxMonData(boxMon, MON_DATA_PERSONALITY, NULL);

      switch (gSpeciesInfo[species].genderRatio)
      {
      case (0x00):
      case (0xFE):
      case (0xFF):
          return gSpeciesInfo[species].genderRatio;
      }

      if (gSpeciesInfo[species].genderRatio > (personality & 0xFF))
          return (0xFE);
      else
          return (0x00);
}

/** u8 GetGenderFromSpeciesAndPersonality(u16 species, u32 personality) */
export function GetGenderFromSpeciesAndPersonality(species: any, personality: any): any {
  switch (gSpeciesInfo[species].genderRatio)
      {
      case (0x00):
      case (0xFE):
      case (0xFF):
          return gSpeciesInfo[species].genderRatio;
      }

      if (gSpeciesInfo[species].genderRatio > (personality & 0xFF))
          return (0xFE);
      else
          return (0x00);
}

/** void SetMultiuseSpriteTemplateToPokemon(u16 speciesTag, u8 battlerPosition) */
export function SetMultiuseSpriteTemplateToPokemon(speciesTag: any, battlerPosition: any): any {
  if (gMonSpritesGfxPtr != NULL)
          gMultiuseSpriteTemplate = gMonSpritesGfxPtr.templates[battlerPosition];
      else if (sMonSpritesGfxManagers[MON_SPR_GFX_MANAGER_A])
          gMultiuseSpriteTemplate = sMonSpritesGfxManagers[MON_SPR_GFX_MANAGER_A].templates[battlerPosition];
      else if (sMonSpritesGfxManagers[MON_SPR_GFX_MANAGER_B])
          gMultiuseSpriteTemplate = sMonSpritesGfxManagers[MON_SPR_GFX_MANAGER_B].templates[battlerPosition];
      else
          gMultiuseSpriteTemplate = gBattlerSpriteTemplates[battlerPosition];

      gMultiuseSpriteTemplate.paletteTag = speciesTag;
      if (battlerPosition == B_POSITION_PLAYER_LEFT || battlerPosition == B_POSITION_PLAYER_RIGHT)
          gMultiuseSpriteTemplate.anims = gAnims_MonPic;
      else if (speciesTag > (500))
          gMultiuseSpriteTemplate.anims = gMonFrontAnimsPtrTable[speciesTag - (500)];
      else
          gMultiuseSpriteTemplate.anims = gMonFrontAnimsPtrTable[speciesTag];
}

/** void SetMultiuseSpriteTemplateToTrainerBack(u16 trainerPicId, u8 battlerPosition) */
export function SetMultiuseSpriteTemplateToTrainerBack(trainerPicId: any, battlerPosition: any): any {
  gMultiuseSpriteTemplate.paletteTag = trainerPicId;
      if (battlerPosition == B_POSITION_PLAYER_LEFT || battlerPosition == B_POSITION_PLAYER_RIGHT)
      {
          gMultiuseSpriteTemplate = sTrainerBackSpriteTemplates[trainerPicId];
          gMultiuseSpriteTemplate.anims = gTrainerBackAnimsPtrTable[trainerPicId];
      }
      else
      {
          if (gMonSpritesGfxPtr != NULL)
              gMultiuseSpriteTemplate = gMonSpritesGfxPtr.templates[battlerPosition];
          else
              gMultiuseSpriteTemplate = gBattlerSpriteTemplates[battlerPosition];
          gMultiuseSpriteTemplate.anims = gTrainerFrontAnimsPtrTable[trainerPicId];
      }
}

/** void SetMultiuseSpriteTemplateToTrainerFront(u16 trainerPicId, u8 battlerPosition) */
export function SetMultiuseSpriteTemplateToTrainerFront(trainerPicId: any, battlerPosition: any): any {
  if (gMonSpritesGfxPtr != NULL)
          gMultiuseSpriteTemplate = gMonSpritesGfxPtr.templates[battlerPosition];
      else
          gMultiuseSpriteTemplate = gBattlerSpriteTemplates[battlerPosition];

      gMultiuseSpriteTemplate.paletteTag = trainerPicId;
      gMultiuseSpriteTemplate.anims = gTrainerFrontAnimsPtrTable[trainerPicId];
}

/** static void EncryptBoxMon(struct BoxPokemon *boxMon) */
export function EncryptBoxMon(boxMon: any): any {
  let i: any = null;
      for (i = 0; i < ARRAY_COUNT(boxMon.secure.raw); i++)
      {
          boxMon.secure.raw[i] ^= boxMon.personality;
          boxMon.secure.raw[i] ^= boxMon.otId;
      }
}

/** static void DecryptBoxMon(struct BoxPokemon *boxMon) */
export function DecryptBoxMon(boxMon: any): any {
  let i: any = null;
      for (i = 0; i < ARRAY_COUNT(boxMon.secure.raw); i++)
      {
          boxMon.secure.raw[i] ^= boxMon.otId;
          boxMon.secure.raw[i] ^= boxMon.personality;
      }
}

/** u32 GetMonData3(struct Pokemon *mon, s32 field, u8 *data) */
export function GetMonData3(mon: any, field: any, data: any): any {
  let ret: any = null;

      switch (field)
      {
      case MON_DATA_STATUS:
          ret = mon.status;
          break;
      case MON_DATA_LEVEL:
          ret = mon.level;
          break;
      case MON_DATA_HP:
          ret = mon.hp;
          break;
      case MON_DATA_MAX_HP:
          ret = mon.maxHP;
          break;
      case MON_DATA_ATK:
          ret = GetDeoxysStat(mon, (1));
          if (!ret)
              ret = mon.attack;
          break;
      case MON_DATA_DEF:
          ret = GetDeoxysStat(mon, (2));
          if (!ret)
              ret = mon.defense;
          break;
      case MON_DATA_SPEED:
          ret = GetDeoxysStat(mon, (3));
          if (!ret)
              ret = mon.speed;
          break;
      case MON_DATA_SPATK:
          ret = GetDeoxysStat(mon, (4));
          if (!ret)
              ret = mon.spAttack;
          break;
      case MON_DATA_SPDEF:
          ret = GetDeoxysStat(mon, (5));
          if (!ret)
              ret = mon.spDefense;
          break;
      case MON_DATA_ATK2:
          ret = mon.attack;
          break;
      case MON_DATA_DEF2:
          ret = mon.defense;
          break;
      case MON_DATA_SPEED2:
          ret = mon.speed;
          break;
      case MON_DATA_SPATK2:
          ret = mon.spAttack;
          break;
      case MON_DATA_SPDEF2:
          ret = mon.spDefense;
          break;
      case MON_DATA_MAIL:
          ret = mon.mail;
          break;
      default:
          ret = GetBoxMonData(mon.box, field, data);
          break;
      }
      return ret;
}

