/** void AdjustFriendship(struct Pokemon *mon, u8 event) */
export function AdjustFriendship(mon: any, event: any): any {
  let species, heldItem;
      let holdEffect: any = null;
      let mod: any = null;

      if (ShouldSkipFriendshipChange())
          return;

      species = GetMonData(mon, MON_DATA_SPECIES_OR_EGG, 0);
      heldItem = GetMonData(mon, MON_DATA_HELD_ITEM, 0);

      if (heldItem == (175))
      {
          if (gMain.inBattle)
              holdEffect = gEnigmaBerries[0].holdEffect;
          else
              holdEffect = gSaveBlock1Ptr.enigmaBerry.holdEffect;
      }
      else
      {
          holdEffect = GetItemHoldEffect(heldItem);
      }

      if (species && species != (412))
      {
          let friendshipLevel: any = 0;
          let friendship: any = GetMonData(mon, MON_DATA_FRIENDSHIP, 0);

          if (friendship > 99)
              friendshipLevel++;
          if (friendship > 199)
              friendshipLevel++;

          if (event == (5))
          {
               
              if (Random() & 1)
                  return;
          }
          if (event == (3))
          {
               
              if (!(gBattleTypeFlags & ((1 << 3))))
                  return;
              if (!(gTrainers[gTrainerBattleOpponent_A].trainerClass == (0x20)
                  || gTrainers[gTrainerBattleOpponent_A].trainerClass == (0x1f)
                  || gTrainers[gTrainerBattleOpponent_A].trainerClass == (0x26)))
                  return;
          }

          mod = sFriendshipEventModifiers[event][friendshipLevel];
          if (mod > 0 && holdEffect == (27))
               
              mod = (150 * mod) / 100;

          friendship += mod;
          if (mod > 0)
          {
              if (GetMonData(mon, MON_DATA_POKEBALL, NULL) == (11))
                  friendship++;
              if (GetMonData(mon, MON_DATA_MET_LOCATION, NULL) == GetCurrentRegionMapSectionId())
                  friendship++;
          }

          if (friendship < 0)
              friendship = 0;
          if (friendship > (255))
              friendship = (255);

          SetMonData(mon, MON_DATA_FRIENDSHIP,friendship);
      }
}

/** void MonGainEVs(struct Pokemon *mon, u16 defeatedSpecies) */
export function MonGainEVs(mon: any, defeatedSpecies: any): any {
  let evs: any = [];
      let evIncrease: any = 0;
      let totalEVs: any = 0;
      let heldItem: any = null;
      let holdEffect: any = null;
      let i, multiplier;

      for (i = 0; i < (6); i++)
      {
          evs[i] = GetMonData(mon, MON_DATA_HP_EV + i, 0);
          totalEVs += evs[i];
      }

      for (i = 0; i < (6); i++)
      {
          if (totalEVs >= (510))
              break;

          if (CheckPartyHasHadPokerus(mon, 0))
              multiplier = 2;
          else
              multiplier = 1;

          switch (i)
          {
          case (0):
              evIncrease = gSpeciesInfo[defeatedSpecies].evYield_HP * multiplier;
              break;
          case (1):
              evIncrease = gSpeciesInfo[defeatedSpecies].evYield_Attack * multiplier;
              break;
          case (2):
              evIncrease = gSpeciesInfo[defeatedSpecies].evYield_Defense * multiplier;
              break;
          case (3):
              evIncrease = gSpeciesInfo[defeatedSpecies].evYield_Speed * multiplier;
              break;
          case (4):
              evIncrease = gSpeciesInfo[defeatedSpecies].evYield_SpAttack * multiplier;
              break;
          case (5):
              evIncrease = gSpeciesInfo[defeatedSpecies].evYield_SpDefense * multiplier;
              break;
          }

          heldItem = GetMonData(mon, MON_DATA_HELD_ITEM, 0);
          if (heldItem == (175))
          {
              if (gMain.inBattle)
                  holdEffect = gEnigmaBerries[0].holdEffect;
              else
                  holdEffect = gSaveBlock1Ptr.enigmaBerry.holdEffect;
          }
          else
          {
              holdEffect = GetItemHoldEffect(heldItem);
          }

          if (holdEffect == (24))
              evIncrease *= 2;

          if (totalEVs + evIncrease > (510))
              evIncrease = (evIncrease + (510)) - (totalEVs + evIncrease);

          if (evs[i] + evIncrease > (255))
          {
              let val1: any = evIncrease + (255);
              let val2: any = evs[i] + evIncrease;
              evIncrease = val1 - val2;
          }

          evs[i] += evIncrease;
          totalEVs += evIncrease;
          SetMonData(mon, MON_DATA_HP_EV + i,evs[i]);
      }
}

