/** u16 GetBattleBGM(void) */
export function GetBattleBGM(): any {
  if (gBattleTypeFlags & ((1 << 12)))
      {
          return (480);
      }
      else if (gBattleTypeFlags & ((1 << 14)))
      {
          return (479);
      }
      else if (gBattleTypeFlags & (((1 << 1)) | ((1 << 25))))
      {
          return (476);
      }
      else if (gBattleTypeFlags & ((1 << 3)))
      {
          let trainerClass: any = null;

          if (gBattleTypeFlags & BATTLE_TYPE_FRONTIER)
              trainerClass = GetFrontierOpponentClass(gTrainerBattleOpponent_A);
          else if (gBattleTypeFlags & ((1 << 26)))
              trainerClass = (0xa);
          else
              trainerClass = gTrainers[gTrainerBattleOpponent_A].trainerClass;

          switch (trainerClass)
          {
          case (0xd):
          case (0x35):
              return (483);
          case (0x3):
          case (0x9):
          case (0xb):
          case (0x31):
              return (475);
          case (0x20):
              return (477);
          case (0x26):
              return (478);
          case (0x32):
              if (gBattleTypeFlags & BATTLE_TYPE_FRONTIER)
                  return (481);
              if (!StringCompare(gTrainers[gTrainerBattleOpponent_A].trainerName, gText_BattleWallyName))
                  return (476);
              return (481);
          case (0x1f):
              return (482);
          case (0x3a):
          case (0x3b):
          case (0x3c):
          case (0x3d):
          case (0x3e):
          case (0x3f):
          case (0x40):
              return (471);
          default:
              return (476);
          }
      }
      else
      {
          return (474);
      }
}

